const _seen: Record<string, Set<string>> = {};
const shuffle = (arr: any[]) => [...arr].sort(() => Math.random() - .5);

export function getUnseen(pool: any[], modeId: string, count: number = 12) {
  if (!_seen[modeId]) _seen[modeId] = new Set();
  const seen = _seen[modeId];
  let available = pool.filter(q => !seen.has(q.q));
  if (available.length < count) { 
    _seen[modeId] = new Set(); 
    available = [...pool]; 
  }
  const picked = shuffle(available).slice(0, count);
  picked.forEach(q => seen.add(q.q));
  return picked;
}

